mapper.select:
SELECT USER_ID AS userId, BASE_MONTH AS baseMonth, INCOME_KIND_CODE AS incomeKindCode, INCOME_AMT AS incomeAmt, INPUT_DATE AS inputDate
  FROM USER_INCOME_MONTH
 WHERE USER_ID = #{userId}
   AND BASE_MONTH BETWEEN #{fromMonth} AND #{toMonth}
 ORDER BY BASE_MONTH

mapper.delete:
DELETE FROM USER_INCOME_MONTH
 WHERE USER_ID = #{userId}
   AND BASE_MONTH = #{baseMonth}

mapper.update:
UPDATE APP_USER
   SET WORK_PERIOD_MONTHS = #{months,jdbcType=NUMERIC}, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}

mapper.delete:
DELETE FROM USER_LOAN
 WHERE USER_ID = #{userId}
   AND BASE_MONTH = #{baseMonth}
   AND SOURCE_CODE = 'MANUAL'

